const PLAN_PRICES = {
  basic: 4.99,
  pro: 9.99,
  enterprise: 29.99
};

const ADDON_PRICES = {
  'extra-storage': 2.5,
  'priority-support': 5
};

export function calculatePrice(plan, addons = []) {
  const basePrice = PLAN_PRICES[plan] || 0;
  const addonPrice = addons.reduce((total, addon) => {
    return total + (ADDON_PRICES[addon] || 0);
  }, 0);

  return basePrice + addonPrice;
}

